/**
 * Recipe photos are copied once to PACE's own Storage (bucket `recipe-images`) and served from
 * there, so the phone never contacts TheMealDB (privacy policy: only search words reach it).
 * Shared with the recipes-proxy Edge Function (scripts/sync-shared.mjs). Pure: I/O is injected.
 */
export const IMAGE_BUCKET = 'recipe-images';
export const MAX_IMAGE_BYTES = 1_000_000;
export const IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/webp'] as const;

/** Only TheMealDB's own image paths are fetched by the server (no SSRF). */
export function isMealDbImageUrl(url: string | null | undefined): url is string {
  if (!url) return false;
  try {
    const u = new URL(url);
    return (
      u.protocol === 'https:' &&
      u.hostname === 'www.themealdb.com' &&
      /^\/images\/media\/meals\/[A-Za-z0-9_.-]+\.(jpe?g|png|webp)$/i.test(u.pathname) &&
      !u.search &&
      !u.username
    );
  } catch {
    return false;
  }
}

export const imagePath = (externalId: string) => {
  if (!/^\d{1,10}$/.test(externalId)) throw new Error('invalid recipe id');
  return `themealdb/${externalId}.jpg`;
};

/**
 * Stored/returned image reference: `storage:recipe-images/<path>`, never an external URL. The app
 * turns it into its own Supabase Storage URL (recipeImageUri), so nothing loads from TheMealDB.
 */
export const IMAGE_REF_PREFIX = `storage:${IMAGE_BUCKET}/`;
export const imageRef = (path: string) => `${IMAGE_REF_PREFIX}${path}`;

/** The public URL for a stored reference, or null for anything else (including old external URLs). */
export function recipeImageUri(ref: string | null | undefined, supabaseUrl: string): string | null {
  if (!ref || !ref.startsWith(IMAGE_REF_PREFIX)) return null;
  const path = ref.slice(IMAGE_REF_PREFIX.length);
  if (!/^themealdb\/\d{1,10}\.jpg$/.test(path)) return null;
  return `${supabaseUrl.replace(/\/$/, '')}/storage/v1/object/public/${IMAGE_BUCKET}/${path}`;
}

export interface MirrorPorts {
  /** Which external ids already have a mirrored image. */
  known(ids: string[]): Promise<Set<string>>;
  /** Fetches a validated TheMealDB URL; null when it isn't a small image. */
  fetchImage(url: string): Promise<{ bytes: Uint8Array; type: string } | null>;
  upload(path: string, bytes: Uint8Array, type: string): Promise<void>;
  remember(externalId: string, path: string): Promise<void>;
}

/**
 * Returns externalId → PACE image reference (or null when there's no usable image). New images are
 * copied a few at a time; a failed copy never fails the request (the recipe shows no photo).
 */
export async function mirrorImages(
  items: readonly { externalId: string; imageUrl: string | null }[],
  ports: MirrorPorts,
  concurrency = 4,
): Promise<Map<string, string | null>> {
  const out = new Map<string, string | null>();
  const valid = items.filter((i) => /^\d{1,10}$/.test(i.externalId));
  const known = await ports.known(valid.map((i) => i.externalId));
  const todo: { externalId: string; imageUrl: string }[] = [];
  for (const i of valid) {
    if (known.has(i.externalId)) out.set(i.externalId, imageRef(imagePath(i.externalId)));
    else if (isMealDbImageUrl(i.imageUrl))
      todo.push({ externalId: i.externalId, imageUrl: i.imageUrl });
    else out.set(i.externalId, null);
  }
  for (let k = 0; k < todo.length; k += concurrency) {
    await Promise.all(
      todo.slice(k, k + concurrency).map(async ({ externalId, imageUrl }) => {
        try {
          const img = await ports.fetchImage(imageUrl);
          if (
            !img ||
            img.bytes.byteLength > MAX_IMAGE_BYTES ||
            !(IMAGE_TYPES as readonly string[]).includes(img.type)
          ) {
            out.set(externalId, null);
            return;
          }
          const path = imagePath(externalId);
          await ports.upload(path, img.bytes, img.type);
          await ports.remember(externalId, path);
          out.set(externalId, imageRef(path));
        } catch {
          out.set(externalId, null);
        }
      }),
    );
  }
  return out;
}
